"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[6127],{1679(e){e.exports=JSON.parse('{"title":"React \ud574\uccb4\ubd84\uc11d\uae30","date":"2026-05-26","coverUrl":"/kudzu-based-bench/assets/notion/d94d358e922ce6b4.png","html":"<h1 data-notion-block-id=\\"36be548d-8a8e-8064-928c-f16b8988762e\\">Beyond the Article: \ud55c \uac78\uc74c \ub354</h1><h2 data-notion-block-id=\\"36be548d-8a8e-80c5-8855-f259734ba6c6\\" id=\\"36be548d-8a8e-80c5-8855-f259734ba6c6\\">React \ud574\uccb4\ubd84\uc11d\uae30</h2><a href=\\"https://tannerlinsley.com/posts/projecting-react\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tannerlinsley.com/posts/projecting-react</a><p data-notion-block-id=\\"36ce548d-8a8e-80fb-a4a2-f6b11c94e58c\\">TanStack\uc758 \uba54\uc778\ud14c\uc774\ub108\uc778 Tanner Linsley\uac00 \uc815\uc791 \uc4f0\uc9c0\ub3c4 \uc54a\ub294 React \uae30\ub2a5\ub4e4\uc774 \uc790\uae30 \ube14\ub85c\uadf8\uc758 \uc804\uc1a1 \uc6a9\ub7c9\uc5d0 \uadf8\ub300\ub85c \uc2e4\ub9ac\ub294 \uac8c \uc65c \ubd88\ud3b8\ud588\ub294\uc9c0, \uadf8\ub807\uae30\uc5d0 React\ub97c Tanstack Start\uc5d0 \ub9de\ub3c4\ub85d AI\ub97c \ud1b5\ud574 \uc7ac\uad6c\uc131\ud55c \uacbd\ud5d8\uacfc AI\ub85c \ub77c\uc774\ube0c\ub7ec\ub9ac/\ud504\ub808\uc784\uc6cc\ud06c\ub97c \uc7ac\uad6c\uc131\ud55c \uac83\uc5d0 \ub300\ud55c \uc0b0\ucd9c\ubb3c\uc5d0 \ub300\ud55c \uc758\uacac\uc744 \ud45c\ucd9c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. Tanstack Start\uc758 React-SSR \ucd5c\uc801\ud654 \uad00\uc810, \uadf8\ub9ac\uace0 <a href=\\"https://newsletter.pragmaticengineer.com/p/the-pulse-cloudflare-rewrites-nextjs\\">Cloudflare\ud300\uc758 vinext \uc7ac\uad6c\uc131\uc5d0 \ub300\ud55c \uc724\ub9ac\uc801/\uc0ac\uc5c5\uc801 \uad00\uc810</a>, \uadf8\ub9ac\uace0 <a href=\\"https://ones-to-watch.ethansup.net/news/post/34ae548d-8a8e-8089-b1db-c322e570f0aa#34ae548d-8a8e-801a-a52c-fe2398c8d164\\">Oxc \ud300\uc758 Claude code / Codex\ub97c \uc5b4\ub5bb\uac8c \ubc14\ub77c\ubcf4\ub294\uc9c0</a>\ub97c \ud568\uaed8 \ubcf4\uc2dc\uba74 \ud504\ub860\ud2b8\uc5d4\ub4dc \ub77c\uc774\ube0c\ub7ec\ub9ac \ub9c8\uc2a4\ud130\ub4e4\uc740 AI\uc5d0 \ub300\ud55c, \uadf8\ub9ac\uace0 AI\ub97c \ud1b5\ud55c \ub77c\uc774\ube0c\ub7ec\ub9ac \uc7ac\uad6c\uc131\uc5d0 \ub300\ud574 \uc5b4\ub5bb\uac8c \uc0dd\uac01\ud558\ub294\uc9c0 \uc0dd\uac01\ud574\ubcfc\ub9cc \ud560 \uac83 \uac19\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"36be548d-8a8e-80a4-b972-c4f4fd8aaece\\" id=\\"36be548d-8a8e-80a4-b972-c4f4fd8aaece\\">Server Function\uc758 \uac1c\ub150\uc801 \uc624\ub958</h2><a href=\\"https://longho.dev/posts/rsc-server-functions-are-not-an-api-boundary/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://longho.dev/posts/rsc-server-functions-are-not-an-api-boundary/</a><p data-notion-block-id=\\"36ce548d-8a8e-80a6-a098-f4d022c5720c\\">RSC\uc758 \uad6c\uc131\uc694\uc18c\uc778 Server Function\uc744 \ud754\ud788 \uc0dd\uac01\ud558\ub294 API \uacbd\uacc4\ub85c \uc5ec\uae30\uba74 \uc548 \ub418\ub294 \uc774\uc720\ub97c, Next.js\uc758 Server Action\uc774 \uc2e4\uc81c\ub85c \uc5b4\ub5bb\uac8c \ub3d9\uc791\ud558\uace0 \uc5b4\ub514\uc11c \ubb38\uc81c\uac00 \uc0dd\uae30\ub294\uc9c0 \ubcf4\uc5ec\uc8fc\uba74\uc11c \uc9da\ub294 \uae00\uc785\ub2c8\ub2e4. \ub354\ubd88\uc5b4 \uc5b8\uc81c \uc4f0\uace0 \uc5b8\uc81c \ud53c\ud574\uc57c \ud558\ub294\uc9c0\uae4c\uc9c0 \uc548\ub0b4\ud569\ub2c8\ub2e4. Client-Server Function \uc5f0\uacb0\uc5d0\uc11c \ubb38\uc81c\uac00 \ub41c <a href=\\"https://ones-to-watch.ethansup.net/news/post/237e548d-8a8e-80c8-8e59-c60afe0411ca\\">LY corp \ucee8\ud37c\ub7f0\uc2a4\uc758 Version Skew \ubb38\uc81c</a>\ub3c4 \uac19\uc774 \ubcf4\uc2dc\uba74 \uc88b\uc744 \uac83 \uac19\uc2b5\ub2c8\ub2e4.</p><h1 data-notion-block-id=\\"36be548d-8a8e-80ef-bfa8-e8dc3edf9738\\">Straight to the Article: \ube5b\ub098\ub294 \uc778\uc0ac\uc774\ud2b8</h1><h2 data-notion-block-id=\\"36be548d-8a8e-809a-a4a8-eb48057bb821\\" id=\\"36be548d-8a8e-809a-a4a8-eb48057bb821\\">\ucee8\ud14c\uc774\ub108 \ubd80\ub4dc\ub7fd\uac8c \uc560\ub2c8\uba54\uc774\uc158\ud558\uae30</h2><a href=\\"https://www.userinterface.wiki/animating-container-bounds\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.userinterface.wiki/animating-container-bounds</a><p data-notion-block-id=\\"36be548d-8a8e-80cf-ba20-e1d510a6bec0\\">width / height\ub97c \uc560\ub2c8\uba54\uc774\ud305 \ud560 \ub54c \uac12\uc774 \ubc14\ub00c\uc5c8\uc744 \ub54c \uc560\ub2c8\uba54\uc774\uc158\uc744 \uc5b4\ub5bb\uac8c \ud574\uc57c \ud558\ub294\uc9c0 \ud301\uc744 \uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"36be548d-8a8e-8077-b510-f544488926ee\\" id=\\"36be548d-8a8e-8077-b510-f544488926ee\\">FE\uc5d0\uc11c\uc758 \ubcf4\uc548</h2><a href=\\"https://certificates.dev/blog/security-in-react-applications\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://certificates.dev/blog/security-in-react-applications</a><p data-notion-block-id=\\"36be548d-8a8e-80b4-ad5d-d214831cc817\\">FE \uac1c\ubc1c\uc790\ub77c\uba74 \uc54c\uc544\uc57c \ud558\ub294 \uae30\ubcf8\uc801\uc778, \ud558\uc9c0\ub9cc \uc911\uc694\ud55c \ubcf4\uc548 \ud3ec\uc778\ud2b8\ub97c \ubaa8\ub450 \uc9da\uc5b4\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"36be548d-8a8e-8044-a1dc-e4d99c4378c2\\" id=\\"36be548d-8a8e-8044-a1dc-e4d99c4378c2\\">Valibot \uc4f0\uc138\uc694(\ubc14\uc774\ub7f4 \ud1a4\uc73c\ub85c)</h2><a href=\\"https://valibot.dev/blog/why-migrate-to-valibot/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://valibot.dev/blog/why-migrate-to-valibot/</a><h2 data-notion-block-id=\\"36be548d-8a8e-8087-a1d8-ddd6f81633b8\\" id=\\"36be548d-8a8e-8087-a1d8-ddd6f81633b8\\">\ub54c\ub85c\ub294, \ud504\ub808\uc784\uc6cc\ud06c\uac00 \ud544\uc694 \uc5c6\ub2e4.</h2><a href=\\"https://evilmartians.com/chronicles/from-react-to-native-web-with-nanotags-a-migration-that-saved-100kb\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://evilmartians.com/chronicles/from-react-to-native-web-with-nanotags-a-migration-that-saved-100kb</a><p data-notion-block-id=\\"36be548d-8a8e-8065-bbe2-c200631664d2\\">React + Ark UI\uc5d0\uc11c nanotag\ub85c \uc62e\uae30\uba74\uc11c \uc65c \ub54c\ub85c\ub294 \ubb34\uac70\uc6b4 \ud504\ub808\uc784\uc6cc\ud06c\uac00 \ud544\uc694\uc5c6\ub294\uc9c0 \uc0dd\uac01\ud574\ubcf4\uac8c \ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"36be548d-8a8e-80c9-9c3e-f83a2963d738\\" id=\\"36be548d-8a8e-80c9-9c3e-f83a2963d738\\">safe-area-inset\uacfc \ubaa8\ubc14\uc77c</h2><a href=\\"https://polypane.app/blog/using-safe-area-inset-to-build-mobile-safe-layouts/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://polypane.app/blog/using-safe-area-inset-to-build-mobile-safe-layouts/</a><h2 data-notion-block-id=\\"36be548d-8a8e-80f9-89eb-ed6adb46926e\\" id=\\"36be548d-8a8e-80f9-89eb-ed6adb46926e\\">\uc811\uadfc\uc131\uc744 \uc6cc\ud06c\ud50c\ub85c\uc6b0\uc640 \uc8fc\uc7a5\uc5d0 \uc790\uc5f0\uc2a4\ub7fd\uac8c \ub179\uc774\ub294 \ubc95</h2><a href=\\"https://stephaniewalter.design/blog/9-accessibility-myths-and-pushbacks-and-how-to-answer-them/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://stephaniewalter.design/blog/9-accessibility-myths-and-pushbacks-and-how-to-answer-them/</a><h2 data-notion-block-id=\\"36be548d-8a8e-8098-8496-f7d1d27d7154\\" id=\\"36be548d-8a8e-8098-8496-f7d1d27d7154\\">TanStack Form \uc785\ubb38</h2><a href=\\"https://frontendmasters.com/blog/introducing-tanstack-form/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://frontendmasters.com/blog/introducing-tanstack-form/</a><h1 data-notion-block-id=\\"36be548d-8a8e-80ad-9ec7-f58f3645f42a\\">Fresh Finds: \ub193\uce58\uc9c0 \ub9d0\uc544\uc57c \ud560 \uc18c\uc2dd</h1><a href=\\"https://tanstack.com/blog/incident-followup\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tanstack.com/blog/incident-followup</a><p data-notion-block-id=\\"36be548d-8a8e-80e6-9bbb-da032da3013b\\">5\uc6d4 11\uc77c, TanStack\uc758 42\uac1c \ud328\ud0a4\uc9c0\uac00 \uc545\uc131 \ucf54\ub4dc\uac00 \uc2ec\uae34 \ucc44 npm\uc5d0 \uc7ac\ubc30\ud3ec\ub41c \uc0ac\uace0\uc758 \uc0ac\ud6c4 \ub300\uc751\uc744 \ub2e4\ub8ec \ub9ac\ubdf0 \uae00\uc785\ub2c8\ub2e4. \uba54\uc778\ud14c\uc774\ub108\uac00 \ud53c\uc2f1\ub2f9\ud558\uac70\ub098 \ud1a0\ud070\uc744 \ub3c4\ub09c\ub2f9\ud55c \uac8c \uc544\ub2c8\ub77c, \ud3d0\uae30\ub41c fork PR\uc774 \ud2b8\ub9ac\uac70\ud55c \uc6cc\ud06c\ud50c\ub85c\uac00 \uacf5\uc720 CI \uce90\uc2dc\ub97c \uc624\uc5fc\uc2dc\ucf30\uace0, \uc774\ud6c4 \uc815\uc0c1\uc801\uc778 main \ubcd1\ud569\uc758 \ub9b4\ub9ac\uc2a4 \uc6cc\ud06c\ud50c\ub85c\uac00 \uadf8 \uce90\uc2dc\ub97c \ubcf5\uc6d0\ud558\uba74\uc11c \ub7ec\ub108 \uba54\ubaa8\ub9ac\uc5d0\uc11c \ub2e8\uba85(short-lived) publish \ud1a0\ud070\uc744 \ud0c8\ucde8\ub2f9\ud55c \uc815\uad50\ud55c \uacf5\uaca9\uc774\uc5c8\uc2b5\ub2c8\ub2e4.</p><a href=\\"https://voidzero.dev/posts/announcing-rolldown-1-0\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://voidzero.dev/posts/announcing-rolldown-1-0</a><p data-notion-block-id=\\"36be548d-8a8e-800f-84b7-e10008a2be97\\">\uace0\uc131\ub2a5 JS \ubc88\ub4e4\ub7ec Rolldown\uc774 1.0 stable\ub85c \ud504\ub85c\ub355\uc158 \ub808\ub514\uac00 \ub418\uc5c8\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4. \uc18d\ub3c4, Rollup \ud50c\ub7ec\uadf8\uc778 \ud638\ud658, \uace0\uc720 \uae30\ub2a5\uc744 \uac16\ucdc4\uace0 \ucd5c\uc2e0 RC\uc5d0\uc11c \ucf54\ub4dc \ubcc0\uacbd \uc5c6\uc774 \uc5c5\uadf8\ub808\uc774\ub4dc\ub41c\ub2e4\uace0 \ud569\ub2c8\ub2e4.</p><a href=\\"https://nodejs.org/en/blog/release/v26.0.0\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nodejs.org/en/blog/release/v26.0.0</a><p data-notion-block-id=\\"36be548d-8a8e-80d5-8839-f4b09a4ea0bd\\">Node.js 26\uc774 \ucd9c\uc2dc\ub418\uc5b4 Temporal API\uac00 \uae30\ubcf8 \ud65c\uc131\ud654\ub418\uace0, V8\uc774 14.6(Upsert, <code>Iterator.concat()</code> \ub4f1)\uc73c\ub85c, Undici\uac00 8.0\uc73c\ub85c \uc62c\ub77c\uac14\uc73c\uba70 <code>http.writeHeader()</code> \uc81c\uac70 \ub4f1 \uc815\ub9ac\uac00 \uc774\ub904\uc84c\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4. 10\uc6d4\uc5d0 LTS\ub85c \uc9c4\uc785\ud569\ub2c8\ub2e4.</p><a href=\\"https://tailwindcss.com/blog/tailwindcss-v4-3\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tailwindcss.com/blog/tailwindcss-v4-3</a><p data-notion-block-id=\\"36be548d-8a8e-8068-9a22-f4ffa81b5b13\\">Tailwind v4.3(\uacfc \ube14\ub85c\uadf8\ub97c \uae5c\ube61\ud55c v4.2)\uc774 \uc2a4\ud06c\ub864\ubc14 \uc720\ud2f8\ub9ac\ud2f0, <code>@container-size</code>, <code>zoom-*</code>\xb7<code>tab-*</code> \uc720\ud2f8\ub9ac\ud2f0, stacked/compound <code>@variant</code> \uc9c0\uc6d0, \uc2e0\uaddc \uc911\ub9bd \ud314\ub808\ud2b8(mauve\xb7olive\xb7mist\xb7taupe), webpack \uc804\uc6a9 \ud50c\ub7ec\uadf8\uc778 \ub4f1\uc744 \ucd94\uac00\ud588\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://waku.gg/blog/waku-v1-beta\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://waku.gg/blog/waku-v1-beta</a><p data-notion-block-id=\\"36be548d-8a8e-8030-b2e7-eba4dcedc29b\\">\ubbf8\ub2c8\uba40 React Server Components \ud504\ub808\uc784\uc6cc\ud06c Waku\uac00 1.0 beta\ub85c, \uc7ac\ubc30\ud3ec \uc2dc \uc774\uc804 \ube4c\ub4dc \ud074\ub77c\uc774\uc5b8\ud2b8\uac00 \uae68\uc9c0\uc9c0 \uc54a\ub294 version skew \ucc98\ub9ac, Vite 8 + Rolldown \ube4c\ub4dc, CSP \uc9c0\uc6d0, Node 26 \uc9c0\uc6d0\uc744 \uac16\ucdc4\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://github.blog/ai-and-ml/github-copilot/how-to-write-a-great-agents-md-lessons-from-over-2500-repositories/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.blog/ai-and-ml/github-copilot/how-to-write-a-great-agents-md-lessons-from-over-2500-repositories/</a><p data-notion-block-id=\\"36be548d-8a8e-80a2-9827-ebf058d2148e\\">GitHub\uc774 2,500\uac1c \uc774\uc0c1\uc758 \uc800\uc7a5\uc18c\ub97c \ubd84\uc11d\ud574 \ud6a8\uacfc\uc801\uc778 <code>agents.md</code> \uc791\uc131\ubc95\uacfc \ud15c\ud50c\ub9bf\xb7\uc2e4\uc81c \uc608\uc2dc\ub97c \uc815\ub9ac\ud55c \uae00\uc785\ub2c8\ub2e4.</p><h3 data-notion-block-id=\\"36ce548d-8a8e-8084-b010-db7b0467337d\\">Ex: AI \ucf54\ub4dc \uc790\uc728\uc8fc\ud589 \uc81c\uc791 \uacfc\uc815</h3><a href=\\"https://workos.com/blog/project-horizon\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://workos.com/blog/project-horizon</a><p data-notion-block-id=\\"36be548d-8a8e-8098-82fc-eedcfafcdf75\\">AI\ub85c \ucf54\ub4dc\ub97c \ube68\ub9ac \uc4f0\ub294 \uac74 \uc774\ubbf8 \ud754\ud558\uc9c0\ub9cc \ubcd1\ubaa9\uc740 \uc5ec\uc804\ud788 \uc624\ucf00\uc2a4\ud2b8\ub808\uc774\uc158 \u2014 \ubb34\uc5c7\uc744 \ud560\uc9c0 \uc815\ud558\uace0, \ucee8\ud14d\uc2a4\ud2b8\ub97c \uc5ee\uace0, \uac80\uc99d\uc744 \ub3cc\ub9ac\uace0, \uc548\uc804\ud558\uac8c \ubc30\ud3ec\ud558\ub294 \uc77c\uc774\ub77c\ub294 \ubb38\uc81c\uc758\uc2dd\uc758 \uae00\uc785\ub2c8\ub2e4. WorkOS\uc5d0\uc11c \uc774\ub97c \uc5b4\ub36f\uac8c \ud574\uacb0\ud588\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><p data-notion-block-id=\\"36ce548d-8a8e-801b-b562-c4e73741fbec\\"></p>"}')}}]);